// The supplied HTML is an interaction reference, never a numeric result source.
let showComputeGraph=true,goldenLayer=false,goldenPanel=null,goldenMode='golden',goldenCell=0,goldenRelated=null;
function goldenMatches(id,e){return e.compute_node_ids.includes(id)}
function computeGoldenGraph(){
 const e=executionModel().events[executionStep],nodes=[['x','X',220,110],['square','X²',400,60],['mean','mean',580,60],['epsilon','+ ε',760,60],['rsqrt','rsqrt',940,60],['norm','× rstd',1120,110],['normGamma','× γ',1280,110],['gamma','γ',1280,220],['output','Y',1430,110]],ports={};
 let s=headerTip(20,5,180,35,tx(30,30,'RMSNorm · 计算图','resource-label'),'计算依赖与源码执行步骤关联；数值层使用本机重算 CPU Golden。');
 for(const [id,label,x,y] of nodes){const active=hasExecutionSelection&&(goldenMatches(id,e)||goldenRelated===id),tensor=['x','gamma','output'].includes(id),circle=['square','epsilon','norm','normGamma'].includes(id),w=tensor?100:circle?48:216,h=tensor?32:circle?48:38.4,left=x+50-w/2;ports[id]={left,right:left+w,top:y,bottom:y+h,cx:x+50,cy:y+h/2};let glyph;
 if(id==='output'&&goldenLayer){ports[id]={left:220,right:1600,top:300,bottom:620,cx:910,cy:460};continue}
 if(tensor)glyph=GridTensor.render(x,y,100,label,active?'#d4d4d4':'#858585',id==='gamma'?'weight':id==='output'?'y':'x');
 else if(circle){glyph=VisualSystem.node(id==='epsilon'?'add':'multiply','compute-'+id,label,0,0);if(active)glyph=glyph.replace('fill="#111"','fill="#d4d4d4"').replaceAll('stroke="#eee"','stroke="#111"');glyph=`<g transform="translate(${left} ${y}) scale(1)">${glyph}</g>`+tx(x+82,y+69,label,'muted');}
 else{const icon=window.PtoOpIcons.find(i=>i.id===(id==='mean'?'reduce':'norm'));glyph=LibraryOpNode({...icon,name:label},0,0).replace('font-size="20"','font-size="28"');if(active)glyph=glyph.replace('fill="#4f4f4f"','fill="#d4d4d4"').replace('fill="#eee" font-size','fill="#111" font-size');glyph=`<g transform="translate(${left} ${y}) scale(.6)">${glyph}</g>`;}
 s+=`<g data-compute="${id}" role="button" tabindex="0" aria-label="${id==='output'?'查看 Y 的 Golden 对照':label+' · 定位执行块'}" data-tip="${id==='output'?'点击展开 Y，逐元素查看 CPU Golden、NPU Mock 和差值':label+'：定位关联源码执行步骤'}">${glyph}${id==='output'?tx(x,y+64,'查看 Golden 对照 ↗','muted'):''}</g>`;
 }
 const path=d=>`<path d="${d}" fill="none" stroke="#777" stroke-width="1.4" marker-end="url(#arrow)"/>`,edge=(a,b)=>path(`M${ports[a].right} ${ports[a].cy}H${ports[b].left}`);
 let wires=path(`M${ports.x.right} ${ports.x.cy}H360V${ports.square.cy}H${ports.square.left}`)+edge('square','mean')+edge('mean','epsilon')+edge('epsilon','rsqrt')+path(`M${ports.rsqrt.right} ${ports.rsqrt.cy}H${ports.norm.cx}V${ports.norm.top}`)+path(`M${ports.x.cx} ${ports.x.bottom}V165H1080V${ports.norm.cy}H${ports.norm.left}`)+edge('norm','normGamma')+path(`M${ports.gamma.cx} ${ports.gamma.top}V${ports.normGamma.bottom}`)+(goldenLayer?path(`M${ports.normGamma.right} ${ports.normGamma.cy}H1480V${ports.output.top}`):edge('normGamma','output'));
 s=wires+s;

 if(goldenLayer)s+=`<g id="compute-output">${inlineGoldenGrid()}</g>`;
 s+=path(`M${ports.output.right} ${ports.output.cy}H1638V${(goldenLayer?770:350)+155+2*(state.object==='estimate'&&selected().feasible?108:82)+18}H1616`);
 return s;
}
function ensureGoldenPanel(){if($('goldenInspector'))return;const p=document.createElement('section');p.id='goldenInspector';p.hidden=true;p.setAttribute('aria-label','原位计算检查');document.body.append(p);const style=document.createElement('style');style.textContent=`#goldenInspector{position:fixed;z-index:12;width:440px;max-width:calc(100vw - 24px);max-height:50vh;overflow:auto;background:#242424;color:#ddd;border-radius:12px;padding:16px;font:12px/1.6 ui-monospace}#goldenInspector[hidden]{display:none}#goldenInspector header{display:flex;justify-content:space-between;font-size:14px}#goldenInspector button{border:0;background:#393939;color:#ddd;border-radius:16px;padding:5px 10px;cursor:pointer;font:inherit}#goldenInspector button[aria-pressed=true]{background:#d4d4d4;color:#111}#goldenInspector button:focus-visible{outline:0;text-decoration:underline}#goldenInspector .modes{display:flex;gap:6px;margin:12px 0}#goldenInspector .cells{display:grid;grid-template-columns:repeat(6,1fr);gap:4px;margin:12px 0}#goldenInspector .cells button{border-radius:3px;min-width:0;width:100%;padding:7px 0;font-size:10px;white-space:nowrap}#goldenInspector p{color:#bbb;margin:10px 0}`;document.head.append(style);
 p.onclick=ev=>{const b=ev.target.closest('button');if(!b)return;if(b.dataset.close!==undefined)goldenPanel=null;if(b.dataset.mode)goldenMode=b.dataset.mode;if(b.dataset.cell!==undefined)goldenCell=+b.dataset.cell;syncGoldenPanel()};
}
function syncGoldenPanel(){ensureGoldenPanel();const p=$('goldenInspector');p.hidden=!goldenPanel||goldenPanel==='output'||!showComputeGraph;if(p.hidden)return;const c=config(),output=goldenPanel==='output',e=executionModel().events[executionStep],values=CPU_GOLDEN.cases[c.id],value=i=>values?.[i],format=v=>v===undefined?'—':Number(v).toPrecision(7);
 p.innerHTML=`<header><span>${output?'Y · 完整输出':esc(e.label)}</span><button data-close data-tip="关闭检查并保留选择与视角" aria-label="关闭原位检查">×</button></header>`+`<p>${e.id==='vf'?(e.phase==='partial'?'X² → 分块平方和 → 部分和':'合并部分和 → ÷ H → + ε → rsqrt'):e.id==='scale'?'X × rstd × γ → Y':e.id==='y'?'UB → MTE3 → 完整输出 Y 的对应分块':e.id==='weight'?'γ · GM → MTE2 → UB':'X · GM → MTE2 → UB'}</p><p>步骤 ${executionStep+1} · 源码顺序，不表示耗时</p><button data-compute="output" data-tip="检查所有写回块共用的完整输出 Y">完整输出 Y</button><p>${refs().map(([path,a,b])=>`<a style="color:#ccc" data-tip="打开当前事件固定版本源码" href="${DATA.sources[path].url}#L${a}-L${b}" target="_blank" rel="noopener">源码 L${a}–${b} ↗</a>`).join(' · ')}</p>`;
 const target=output?document.querySelector('[data-compute="output"]'):document.querySelector('.event-button[data-step="'+executionStep+'"]');if(!target)return;const a=target.getBoundingClientRect(),w=p.offsetWidth,h=p.offsetHeight;let left=a.right+12,top=a.top;if(left+w>innerWidth-12)left=a.left-w-12;if(left<12){left=Math.max(12,Math.min(innerWidth-w-12,a.left));top=a.bottom+12}top=Math.max(75,Math.min(innerHeight-h-85,top));p.style.left=left+'px';p.style.top=top+'px';
}
function goldenClick(ev){const cell=ev.target.closest('[data-golden-cell]');if(cell){ev.preventDefault();ev.stopImmediatePropagation();goldenCell=+cell.dataset.goldenCell;render();return}const node=ev.target.closest('[data-compute]'),step=ev.target.closest('.event-button[data-step]');if(!node&&!step)return;if(typeof moved!=='undefined'&&moved)return;ev.preventDefault();ev.stopImmediatePropagation();$('inspector').hidden=true;$('tooltip').hidden=true;
 if(node){const id=node.dataset.compute;if(id==='toggle'){goldenLayer=!goldenLayer;goldenMode=goldenLayer?'golden':'npu';goldenPanel=null;goldenRelated=goldenLayer?'output':null;render();fit();return}if(id==='output'){goldenLayer=!goldenLayer;goldenPanel=null;goldenRelated=goldenLayer?'output':null;render();fit();return}const events=executionModel().events;let ix=events.findIndex((e,i)=>i>=executionStep&&goldenMatches(id,e));if(ix<0)ix=events.findIndex(e=>goldenMatches(id,e));goldenPanel=null;goldenRelated=id;if(ix>=0)setExecutionStep(ix)}else{goldenRelated=null;goldenPanel='event';setExecutionStep(+step.dataset.step)}
}
document.addEventListener('click',goldenClick,true);
document.addEventListener('keydown',e=>{if(e.key==='Escape'){goldenPanel=null;syncGoldenPanel()}if(['Enter',' '].includes(e.key)&&e.target.matches('[data-compute],[data-golden-cell],.event-button[data-step]'))goldenClick(e)},true);

// Explicitly constructed NPU values, never presented as device measurements.
function mockNpuValue(g,i){return Math.fround(g*(1+((i%7)-3)*0.000012)+((i%3)-1)*0.000002)}
function inlineGoldenGrid(){
 const values=CPU_GOLDEN.cases[config().id];if(!values)return headerTip(220,300,1200,45,tx(230,325,'当前 dtype 无匹配 Golden 数组','caption'),'仅固定 FP32 host 源码具有本机重算结果。');
 const verdict=goldenVerdict(values);
 const text=(x,y,t,size=13,color='#bbb')=>`<text x="${x}" y="${y}" style="font-size:${size}px;fill:${color}">${esc(t)}</text>`;
 let s=`<rect x="210" y="300" width="1395" height="435" rx="8" fill="#181818"/><g data-compute="output" tabindex="0" role="button" aria-label="收起 Y 数值 Tensor" data-tip="收起数值网格，恢复 Y Tensor"><rect x="1552" y="306" width="36" height="32" rx="5" fill="transparent"/><path d="M1562 316h7v7m0-7-8 8M1579 329h-7v-7m0 7 8-8" stroke="#bbb" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" fill="none"/></g>`+text(230,330,'Y · r[0:4], c[0:6]   NPU Mock / CPU Golden / Δ = NPU − Golden',16)+text(230,353,'相同索引直接对照 · NPU 为构造值，未执行设备校验',12);
 for(let i=0;i<24;i++){const x=220+(i%6)*230,y=370+Math.floor(i/6)*56,g=Math.fround(values[i]),v=mockNpuValue(g,i),diff=v-g,active=i===goldenCell;
 s+=`<g data-golden-cell="${i}" tabindex="0" role="button" aria-label="Y[${Math.floor(i/6)},${i%6}] NPU Mock ${v}，Golden ${g}，差值 ${diff}" data-tip="Y[${Math.floor(i/6)}, ${i%6}] · NPU Mock ${v.toPrecision(8)} · CPU Golden ${g.toPrecision(8)} · Δ ${diff.toExponential(3)}"><rect x="${x}" y="${y}" width="222" height="49" rx="3" fill="${active?'#d4d4d4':'#252525'}"/>${verdict.failed.includes(i)?`<rect x="${x+170}" y="${y+3}" width="48" height="17" rx="3" fill="var(--ss-anomaly, #FD5644)"/>${text(x+178,y+15,'超差',11,'#111')}`:''}${text(x+8,y+17,`[${Math.floor(i/6)},${i%6}]  ${v.toPrecision(6)}`,13,active?'#111':'#ddd')}${text(x+8,y+36,`G ${g.toPrecision(6)}  Δ ${diff.toExponential(1)}`,11,active?'#222':'#aaa')}</g>`;
 }
 const g=Math.fround(values[goldenCell]),v=mockNpuValue(g,goldenCell);return s+goldenRuleControls(verdict,text)+text(230,610,`Y[${Math.floor(goldenCell/6)},${goldenCell%6}]   NPU Mock ${v.toPrecision(8)}   Golden ${g.toPrecision(8)}   |Δ| ${Math.abs(v-g).toExponential(4)}`,13);
}

const goldenPolicies={};
function currentGoldenPolicy(){return goldenPolicies[config().id]||(goldenPolicies[config().id]={mode:'source',atol:'',rtol:''})}
function goldenVerdict(values){const p=currentGoldenPolicy(),configured=p.mode==='source'||(p.atol!==''&&p.rtol!==''&&Number.isFinite(+p.atol)&&Number.isFinite(+p.rtol)&&+p.atol>=0&&+p.rtol>=0);let maxAbs=0,maxRel=0,maxSourceRel=0;const failed=[];
 values.forEach((raw,i)=>{const g=Math.fround(raw),n=mockNpuValue(g,i),d=Math.abs(n-g),rel=g===0?(d===0?0:Infinity):d/Math.abs(g),sourceRel=d/(Math.abs(g)+1e-6);maxAbs=Math.max(maxAbs,d);maxRel=Math.max(maxRel,rel);maxSourceRel=Math.max(maxSourceRel,sourceRel);if(configured&&!(p.mode==='source'?sourceRel<2e-3:d<=+p.atol+(+p.rtol)*Math.abs(g)))failed.push(i)});
 return {configured,failed,maxAbs,maxRel,maxSourceRel};
}
function goldenRuleControls(v,text){const p=currentGoldenPolicy(),c=config(),summary=v.configured?`Mock 数值样本 ${v.failed.length?'数值超差':'通过'} · 失败 ${v.failed.length}/24`:'未判定 · 请设置 atol 与 rtol';
 return text(230,636,`${summary} · maxAbs ${v.maxAbs.toExponential(3)} · maxRel ${v.maxRel.toExponential(3)}`,14)+text(230,657,`${c.shape.join(' × ')} / ${c.dtype.toUpperCase()} · 仅 r[0:4], c[0:6] / Tile 0；非全张量；橙红 = 数值超差，非性能判定`,12)+`<foreignObject x="230" y="670" width="1340" height="58"><div xmlns="http://www.w3.org/1999/xhtml" data-golden-policy="true" style="display:flex;align-items:center;gap:12px;color:#ccc;font:13px monospace"><select aria-label="样本判定规范" data-tip="固定源码相对误差规则，或自定义 allclose 容差" data-policy="mode" style="background:#333;color:#ddd;border:0;padding:7px"><option value="source" ${p.mode==='source'?'selected':''}>源码 FP32：|Δ| / (|G| + 1e-6) &lt; 0.002</option><option value="custom" ${p.mode==='custom'?'selected':''}>自定义：|Δ| ≤ atol + rtol × |G|</option></select>${p.mode==='custom'?`<label>atol <input aria-label="绝对容差 atol" data-tip="当前 Shape / Dtype 的自定义非负绝对容差" data-policy="atol" type="number" min="0" step="any" value="${esc(p.atol)}" style="width:110px;background:#333;color:#ddd;border:0;padding:7px"/></label><label>rtol <input aria-label="相对容差 rtol" data-tip="当前 Shape / Dtype 的自定义非负相对容差" data-policy="rtol" type="number" min="0" step="any" value="${esc(p.rtol)}" style="width:110px;background:#333;color:#ddd;border:0;padding:7px"/></label>`:''}</div></foreignObject>`;
}
document.addEventListener('change',e=>{if(!e.target.dataset.policy)return;currentGoldenPolicy()[e.target.dataset.policy]=e.target.value;render()});
document.addEventListener('pointerdown',e=>{if(e.target.closest('[data-golden-policy]'))e.stopPropagation()},true);

document.addEventListener('input',e=>{if(e.target.matches('input[data-policy]'))currentGoldenPolicy()[e.target.dataset.policy]=e.target.value});
document.addEventListener('focusout',e=>{if(e.target.matches('input[data-policy]')){currentGoldenPolicy()[e.target.dataset.policy]=e.target.value;render()}});
